    pub type LoadedFiles = List<LoadedFile>;

    #[inline]
    pub fn load_base() -> Int {
        int_lit(1000000000)
    }

    pub fn loaded_based(mut fs: LoadedFiles, mut base: Int) -> LoadedFiles {
        loop {
            if null_p(fs) {
                return nil::<Product_11_12_13_14_15_16_17_18<Int, Int, Str, Str, List<&'static mx::Syn>, Str, Str, bool>>();
            } else if (_gt(base, int_lit(0)) && _eq(car(fs).1, base)) {
                return the::<LoadedFiles>(kayak_rt::heap_cons(car(fs), nil::<Product_11_12_13_14_15_16_17_18<Int, Int, Str, Str, List<&'static mx::Syn>, Str, Str, bool>>()));
            } else {
                fs = cdr(fs);
                continue;
            }
        }
    }

    pub fn text_place(text: Str, at: Int) -> Str {
        let go__knot = knot::<&'static (dyn Fn(Int, Int, Int) -> Str + Send + Sync)>();
        let go = lambda3s(move |mut i: Int, mut line: Int, mut col: Int| {
            loop {
                if (_gt_eq(i, at) || _gt_eq(i, string_length(text))) {
                    return string_append(int_to_string(line), string_append(str_lit(":"), int_to_string(col)));
                } else if char_eq_p(string_ref(text, i), '\n') {
                    (i, line, col) = (_plus(i, int_lit(1)), _plus(line, int_lit(1)), int_lit(1));
                    continue;
                } else {
                    (i, col) = (_plus(i, int_lit(1)), _plus(col, int_lit(1)));
                    continue;
                }
            }
        });
        go__knot.set(go);
        go(int_lit(0), int_lit(1), int_lit(1))
    }

    pub fn in_loaded_as(fs: LoadedFiles, base: Int, path: Str, m: Str, at: Int) -> Str {
        let f = loaded_based(fs, base);
        if (null_p(f) || _lt(at, base) || _gt_eq(at, _plus(base, load_base()))) {
            m
        } else {
            string_append(str_lit("in `"), string_append(path, string_append(str_lit("`, "), string_append(text_place(car(f).5, _minus(at, base)), string_append(str_lit(": "), m)))))
        }
    }

