    pub fn mu_new() -> Int {
        let n = get(nmus());
        if _eq(n, array_length(get(mus()))) {
            let bigger = the::<Array<&'static Sty>>(make_array(_star(int_lit(2), n), s_nil()));
            copy_stys(get(mus()), bigger, int_lit(0));
            set(mus(), bigger)
        } else {
            ()
        };
        set(nmus(), _plus(n, int_lit(1)));
        n
    }

