    pub fn ix_kept(ix: &'static Index, n: Symbol, h: Int, d: bool, b: Int) -> &'static Index {
        let tagcase_ = ix;
        match *tagcase_ {
            Index::IxNode(k, m, e, x, l, r) => {
                if _lt(h, k) {
                    ix_node(k, m, e, x, ix_kept(l, n, h, d, b), r)
                } else if (_eq(h, k) && symbol_eq_p(n, m) && mx_eq_p(d, e)) {
                    ix
                } else {
                    ix_node(k, m, e, x, l, ix_kept(r, n, h, d, b))
                }
            }
            _ => {
                let y = tagcase_;
                ix_node(h, n, d, b, ix_leaf(), ix_leaf())
            }
        }
    }

    pub fn indexed(mut r#as: Atms, mut ix: &'static Index, mut name: Namer) -> &'static Index {
        loop {
            if null_p(r#as) {
                return ix;
            } else {
                (r#as, ix) = (cdr(r#as), {
                    let tagcase_ = car(r#as);
                    match *tagcase_ {
                        Atm::AtmLit(b, d) => {
                            let m = name(b);
                            if null_p(m) {
                                ix
                            } else {
                                ix_kept(ix, car(m), symbol_name_hash(car(m)), d, b)
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            ix
                        }
                    }
                });
                continue;
            }
        }
    }

    pub fn mx_env_indexed_grouped(mut ls: Levels, mut ix: &'static Index, mut open: bool, mut name: Namer) -> MxEnvIndexedGroups {
        loop {
            if null_p(ls) {
                if open {
                    return kayak_rt::heap_cons(gr_names(ix), kayak_rt::nil());
                } else {
                    return nil::<&'static mx::Group>();
                }
            } else {
                let tagcase_ = car(ls);
                match *tagcase_ {
                    Level::LvRib(r#as) => {
                        (ls, ix, open) = (cdr(ls), indexed(r#as, ix, name), true);
                        continue;
                    }
                    Level::LvEarlier(r#as) => {
                        (ls, ix, open) = (cdr(ls), indexed(r#as, ix, name), true);
                        continue;
                    }
                    Level::LvCage(c) => {
                        ls = cdr(ls);
                        continue;
                    }
                    Level::LvShape(m) => {
                        let rest = kayak_rt::heap_cons(gr_shape(m), mx_env_indexed_grouped(cdr(ls), ix_leaf(), false, name));
                        if open {
                            return kayak_rt::heap_cons(gr_names(ix), rest);
                        } else {
                            return rest;
                        }
                    }
                }
            }
        }
    }

    pub fn env_within(e: &'static MxEnvIndexedEnv, ls: Levels, name: Namer) -> &'static MxEnvIndexedEnv {
        let x = down_env(e);
        env_of(Product_11_12(append(ls, x.0), append(mx_env_indexed_grouped(ls, ix_leaf(), false, name), x.1)))
    }

