    pub fn any_shape_group_p(mut gs: MxEnvIndexedGroups) -> bool {
        loop {
            if not(null_p(gs)) {
                if {
                    let tagcase_ = car(gs);
                    match *tagcase_ {
                        Group::GrShape(m) => {
                            true
                        }
                        _ => {
                            let y = tagcase_;
                            false
                        }
                    }
                } {
                    return true;
                } else {
                    gs = cdr(gs);
                    continue;
                }
            } else {
                return false;
            }
        }
    }

