    pub fn ix_find(mut ix: &'static Index, mut n: Symbol, mut h: Int, mut d: bool) -> Int {
        loop {
            let tagcase_ = ix;
            match *tagcase_ {
                Index::IxNode(k, m, e, x, l, r) => {
                    if _lt(h, k) {
                        ix = l;
                        continue;
                    } else if (_eq(h, k) && symbol_eq_p(n, m) && mx_eq_p(d, e)) {
                        return x;
                    } else {
                        ix = r;
                        continue;
                    }
                }
                _ => {
                    let y = tagcase_;
                    return int_lit(-1);
                }
            }
        }
    }

    pub fn mx_env_indexed_dropped(mut gs: MxEnvIndexedGroups, mut k: Int) -> MxEnvIndexedGroups {
        loop {
            if (_eq(k, int_lit(0)) || null_p(gs)) {
                return gs;
            } else {
                (gs, k) = (cdr(gs), _minus(k, int_lit(1)));
                continue;
            }
        }
    }

    pub fn looked_in(mut gs: MxEnvIndexedGroups, mut n: Symbol, mut h: Int, mut d: bool, mut k: Int) -> Looked {
        loop {
            if null_p(gs) {
                return Product_11_12_13(int_lit(-1), int_lit(-1), k);
            } else {
                let next = _plus(k, int_lit(1));
                let tagcase_ = car(gs);
                match *tagcase_ {
                    Group::GrNames(ix) => {
                        let b = ix_find(ix, n, h, d);
                        if _gt_eq(b, int_lit(0)) {
                            return Product_11_12_13(int_lit(0), b, next);
                        } else {
                            (gs, k) = (cdr(gs), next);
                            continue;
                        }
                    }
                    Group::GrShape(m) => {
                        return Product_11_12_13(int_lit(1), m, next);
                    }
                }
            }
        }
    }

    #[inline]
    pub fn env_lookup(e: &'static MxEnvIndexedEnv, n: Symbol, d: bool, from: Int, name: Namer) -> Looked {
        looked_in(mx_env_indexed_dropped(down_env(e).1, from), n, symbol_name_hash(n), d, from)
    }

