    pub fn mx_nodes_inserted(x: Str, ys: MxNodesStrings) -> MxNodesStrings {
        if null_p(ys) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if string_lt_p(x, car(ys)) {
            kayak_rt::heap_cons(x, ys)
        } else if string_eq_p(x, car(ys)) {
            ys
        } else {
            kayak_rt::heap_cons(car(ys), mx_nodes_inserted(x, cdr(ys)))
        }
    }

