    pub fn array_grown<T: Copy + 'static>(a: Array<T>, fill: T) -> Array<T> {
        let b = the::<Array<T>>(make_array(_star(int_lit(2), array_length(a)), fill));
        let copied__knot = knot::<&'static dyn Fn(Int) -> ()>();
        let copied = lambda1(move |mut i: Int| {
            loop {
                if _eq(i, array_length(a)) {
                    return ();
                } else {
                    array_set_x(b, i, array_ref(a, i));
                    i = _plus(i, int_lit(1));
                    continue;
                }
            }
        });
        copied__knot.set(copied);
        copied(int_lit(0));
        b
    }

