    pub fn rules_dots() -> Str {
        string_append(str_lit("`...` in a macro a template defines is the template's (R7RS), and repeats "), str_lit("nothing here: the defined macro's is written `(... ...)`"))
    }

    #[inline]
    pub fn rules_procedural() -> Str {
        string_append(str_lit("a template's `define-syntax` defines a `syntax-rules` macro: a procedural "), str_lit("one's transformer is phase 1's code, not yet in a template"))
    }

    pub fn define_syntax_sig(signed: bool) -> &'static Sty {
        let rest = s_pair(s_rules(), s_nil());
        s_export(s_pair(s_bvar(), if signed {
            s_pair(s_data(), rest)
        } else {
            rest
        }), bind_rib(kayak_rt::heap_cons(Product_11_12(kayak_rt::heap_cons(true, kayak_rt::nil()), int_lit(1)), kayak_rt::nil())))
    }

    #[inline]
    pub fn rules_define_sig() -> &'static Sty {
        s_pair(s_rules(), s_pair(s_rules(), s_pair(s_data(), s_pair(s_rules(), s_nil()))))
    }

    pub fn rules_define_p(s: &'static Syn) -> bool {
        let items = proper_items(s);
        (_eq(len(items), int_lit(4)) && syn_symbol_p(car(items)) && string_eq_p(syn_name(car(items)), str_lit("define-syntax")))
    }

    #[inline]
    pub fn rules_escape() -> Str {
        str_lit("`(... template)` other than `(... ...)`: not yet")
    }

    pub fn sig_of(mut n: Symbol, mut mx_types_named: MxTypesNamed) -> Stys {
        loop {
            if null_p(mx_types_named) {
                return nil::<&'static mx::Sty>();
            } else if symbol_eq_p(n, car(mx_types_named).0) {
                return kayak_rt::heap_cons(car(mx_types_named).1, kayak_rt::nil());
            } else {
                mx_types_named = cdr(mx_types_named);
                continue;
            }
        }
    }

    #[inline]
    pub fn percent_found() -> Ref<bool> {
        kayak_rt::kept_constant!(ONCE: Ref<bool>);
        once(&ONCE, || {
            kayak_rt::heap_new(false)
        })
    }

    #[inline]
    pub fn percent_names() -> Ref<MxParserTypesNames> {
        kayak_rt::kept_constant!(ONCE: Ref<MxParserTypesNames>);
        once(&ONCE, || {
            kayak_rt::heap_new(nil::<Symbol>())
        })
    }

    pub fn percent_of(mut ns: MxTypesNamed) -> MxParserTypesNames {
        loop {
            if null_p(ns) {
                return nil::<Symbol>();
            } else if {
                let h = symbol_to_string(car(ns).0);
                (_gt(string_length(h), int_lit(0)) && string_eq_p(substring(h, int_lit(0), int_lit(1)), str_lit("%")))
            } {
                return kayak_rt::heap_cons(car(ns).0, percent_of(cdr(ns)));
            } else {
                ns = cdr(ns);
                continue;
            }
        }
    }

    #[inline]
    pub fn percent_named(kernel: MxTypesNamed) -> MxParserTypesNames {
        if get(percent_found()) {
            ()
        } else {
            set(percent_names(), percent_of(kernel));
            set(percent_found(), true)
        };
        get(percent_names())
    }

    pub fn any_unquotes_p(mut xs: SynsA) -> bool {
        loop {
            if not(null_p(xs)) {
                if unquotes_p(car(xs)) {
                    return true;
                } else {
                    xs = cdr(xs);
                    continue;
                }
            } else {
                return false;
            }
        }
    }

    pub fn unquotes_p(mut s: &'static Syn) -> bool {
        loop {
            let tagcase_ = s;
            match *tagcase_ {
                Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                    return any_unquotes_p(items);
                }
                Syn::Dotted(items, tail, d, a, b, x) => {
                    if any_unquotes_p(items) {
                        return true;
                    } else {
                        s = tail;
                        continue;
                    }
                }
                Syn::Vec(items, d, a, b, x) => {
                    return any_unquotes_p(items);
                }
                _ => {
                    let y = tagcase_;
                    return (syn_symbol_p(s) && (string_eq_p(syn_name(s), str_lit("unquote")) || string_eq_p(syn_name(s), str_lit("unquote-splicing"))));
                }
            }
        }
    }

    pub fn constructs_p(hd: &'static Syn, ps: Pvars) -> Result<bool, Unwind> {
        Ok((syn_keyword_p(hd) || (syn_symbol_p(hd) && pvar_p(syn_symbol(hd)?, ps) && _eq(mx_types_kind_of(car(pvar_of(syn_symbol(hd)?, ps)).0), int_lit(5)))))
    }

    pub fn defines_p(mx_fail: Fails, s: &'static Syn) -> Result<bool, Unwind> {
        let items = proper_items(s);
        let head = if (not(null_p(items)) && syn_symbol_p(car(items))) {
            syn_name(car(items))
        } else {
            str_lit("")
        };
        if string_eq_p(head, str_lit("")) {
            Ok(false)
        } else if string_eq_p(head, str_lit("begin")) {
            Ok((not(null_p(cdr(items))) && all_define_p(mx_fail, cdr(items))?))
        } else {
            let n = syn_symbol(car(items))?;
            Ok((not(null_p(sig_of(n, kernel_definitions(mx_fail)?))) || not(null_p(sig_of(n, scope_definitions(mx_fail)?)))))
        }
    }

    pub fn all_define_p(mut mx_fail: Fails, mut xs: SynsA) -> Result<bool, Unwind> {
        loop {
            if null_p(xs) {
                return Ok(true);
            } else {
                if defines_p(mx_fail, car(xs))? {
                    xs = cdr(xs);
                    continue;
                } else {
                    return Ok(false);
                }
            }
        }
    }

