    pub fn class_of(mx_fail: Fails, it: MxInferItem, lits: LitsOf) -> Result<&'static Class, Unwind> {
        let s = it.1;
        let x = ellipsis_of(s);
        if not(null_p(x)) {
            Ok(cl_seq(car(x)))
        } else if syn_symbol_p(s) {
            let name = syn_name(s);
            if string_eq_p(name, str_lit("_")) {
                Ok(cl_wild())
            } else if string_eq_p(name, str_lit("...")) {
                match fail_at(mx_fail, str_lit("`...` follows the part it repeats, last in a list"), s)? {};
                Ok(cl_wild())
            } else if (mx_types_name_in_p(syn_symbol(s)?, nth_names(lits, it.0)) || reserved_p(name)) {
                Ok(cl_lit(syn_symbol(s)?))
            } else {
                Ok(cl_var(syn_symbol(s)?))
            }
        } else if syn_nil_p(s) {
            Ok(cl_nil())
        } else if null_p(split(s)) {
            Ok(cl_wild())
        } else {
            let tagcase_ = s;
            match *tagcase_ {
                Syn::Vec(i, d, a, b, y) => {
                    Ok(cl_wild())
                }
                _ => {
                    let z = tagcase_;
                    Ok(cl_pair(car(split(s)), nth(split(s), int_lit(1))))
                }
            }
        }
    }

