    pub fn take(mut mx_fail: Fails, mut it: MxInferItem, mut c: MxInferCx, mut acc: Took) -> Result<List<Took>, Unwind> {
        loop {
            let (cid, depth, es, vs, tk, sq) = (it.0, it.2, acc.0, acc.1, acc.2, acc.3);
            let tagcase_ = class_of(mx_fail, it, c.0)?;
            match *tagcase_ {
                Class::ClNil() => {
                    return Ok(kayak_rt::heap_cons(acc, kayak_rt::nil()));
                }
                Class::ClWild() => {
                    return Ok(kayak_rt::heap_cons(acc, kayak_rt::nil()));
                }
                Class::ClSeq(x) => {
                    return Ok(kayak_rt::heap_cons(Product_11_12_13_14(append(es, the::<MxInferItems>(kayak_rt::heap_cons(Product_11_12_13(cid, x, _plus(depth, int_lit(1))), kayak_rt::nil()))), vs, tk, true), kayak_rt::nil()));
                }
                Class::ClVar(n) => {
                    return Ok(kayak_rt::heap_cons(Product_11_12_13_14(es, append(vs, the::<Vars>(kayak_rt::heap_cons(Product_11_12_13_14(cid, n, int_lit(0), depth), kayak_rt::nil()))), tk, sq), kayak_rt::nil()));
                }
                Class::ClPair(a, d) => {
                    (it, acc) = (Product_11_12_13(cid, d, depth), Product_11_12_13_14(append(es, the::<MxInferItems>(kayak_rt::heap_cons(Product_11_12_13(cid, a, depth), kayak_rt::nil()))), vs, true, sq));
                    continue;
                }
                Class::ClLit(n) => {
                    return Ok(nil::<Product_11_12_13_14<List<Product_11_12_13<Int, &'static mx::Syn, Int>>, List<Product_11_12_13_14<Int, Symbol, Int, Int>>, bool, bool>>());
                }
            }
        }
    }

    pub fn take_each(mut mx_fail: Fails, mut its: MxInferItems, mut c: MxInferCx, mut acc: Took) -> Result<List<Took>, Unwind> {
        loop {
            if null_p(its) {
                return Ok(kayak_rt::heap_cons(acc, kayak_rt::nil()));
            } else {
                let t = take(mx_fail, car(its), c, acc)?;
                if null_p(t) {
                    return Ok(nil::<Product_11_12_13_14<List<Product_11_12_13<Int, &'static mx::Syn, Int>>, List<Product_11_12_13_14<Int, Symbol, Int, Int>>, bool, bool>>());
                } else {
                    (its, acc) = (cdr(its), car(t));
                    continue;
                }
            }
        }
    }

    pub type Kds = List<&'static Kd>;

