        loop {
            if null_p(a) {
                return null_p(b);
            } else {
                if not(null_p(b)) {
                    if string_eq_p(car(a), car(b)) {
                        (a, b) = (cdr(a), cdr(b));
                        continue;
                    } else {
                        return false;
                    }
                } else {
                    return false;
                }
            }
        }
