    pub fn provisional(us: Unsigneds, tys: Stys, makes: MxInferInts) -> MacroEnv {
        if null_p(us) {
            nil::<Product_11_12<Symbol, Product_11_12_13_14<&'static mx::Sty, List<Product_11_12_13_14_15_16_17_18<&'static mx::Syn, &'static mx::Syn, List<Product_11_12<List<bool>, &'static mx::Action>>, List<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>, List<Product_11_12<Symbol, &'static mx::Syn>>, Product_11_12_13<Int, Symbol, List<Symbol>>, List<Product_11_12<Symbol, Int>>, List<Int>>>, List<&'static mx::Syn>, Int>>>()
        } else {
            kayak_rt::heap_cons(Product_11_12(car(us).0, Product_11_12_13_14(car(tys), nil::<Product_11_12_13_14_15_16_17_18<&'static mx::Syn, &'static mx::Syn, List<Product_11_12<List<bool>, &'static mx::Action>>, List<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>, List<Product_11_12<Symbol, &'static mx::Syn>>, Product_11_12_13<Int, Symbol, List<Symbol>>, List<Product_11_12<Symbol, Int>>, List<Int>>>(), nil::<&'static mx::Syn>(), car(makes))), provisional(cdr(us), cdr(tys), cdr(makes)))
        }
    }

