    pub fn syn_at_addr(mut s: &'static Syn, mut a: Addr) -> SynsA {
        loop {
            if null_p(a) {
                return kayak_rt::heap_cons(s, kayak_rt::nil());
            } else if null_p(split(s)) {
                return nil::<&'static mx::Syn>();
            } else {
                (s, a) = (if car(a) {
                    car(split(s))
                } else {
                    nth(split(s), int_lit(1))
                }, cdr(a));
                continue;
            }
        }
    }

    pub fn name_in_from_p(mut n: Symbol, mut ns: MxParserTypesNames, mut k: Int) -> bool {
        loop {
            if null_p(ns) {
                return false;
            } else if _gt(k, int_lit(0)) {
                (ns, k) = (cdr(ns), _minus(k, int_lit(1)));
                continue;
            } else {
                if symbol_eq_p(n, car(ns)) {
                    return true;
                } else {
                    (ns, k) = (cdr(ns), int_lit(0));
                    continue;
                }
            }
        }
    }

    pub fn same_signature_p(mx_fail: Fails, n: Symbol, said: &'static Syn) -> Result<bool, Unwind> {
        let (have, want) = (car(macro_of(n, get(defined()))), signature_of(mx_fail, said)?);
        Ok((null_p(want.0) && null_p(have.2) && _eq(have.3, want.2) && sub_p(have.0, want.1, nil::<Product_11_12<&'static mx::Sty, &'static mx::Sty>>()) && sub_p(want.1, have.0, nil::<Product_11_12<&'static mx::Sty, &'static mx::Sty>>())))
    }

    pub fn syntax_held_each(mut mx_fail: Fails, mut name: Symbol, mut s: &'static Syn, mut from: Int, mut es: Entries) -> Result<(), Unwind> {
        loop {
            if null_p(es) {
                return Ok(());
            } else {
                let d = car(es).1;
                if _lt(d, int_lit(100)) {
                    es = cdr(es);
                    continue;
                } else {
                    let said = syntax_sig_of(d);
                    let shown = show_syn(said);
                    let part = syn_at_addr(nth(split(s), int_lit(1)), car(es).0);
                    let x = if (not(null_p(part)) && syn_symbol_p(car(part))) {
                        syn_name(car(part))
                    } else {
                        str_lit("")
                    };
                    let refused = lambda1(move |m: Str| {
                        Ok(match mx_fail(string_append(str_lit("a use of `"), string_append(symbol_to_string(name), string_append(str_lit("`: "), m))), syn_start(s), syn_end(s))? {})
                    });
                    if string_eq_p(x, str_lit("")) {
                        return Ok(match refused(string_append(str_lit("its signature says a macro of `"), string_append(shown, string_append(str_lit("` is "), str_lit("defined at a part that is not a name")))))? {});
                    } else if not(name_in_from_p(string_to_symbol(x), get(made_syntax()), from)) {
                        return Ok(match refused(string_append(str_lit("its signature says it defines `"), string_append(x, string_append(str_lit("`, a macro "), string_append(str_lit("of `"), string_append(shown, str_lit("`, and its expansion does not")))))))? {});
                    } else if not(same_signature_p(mx_fail, string_to_symbol(x), said)?) {
                        return Ok(match refused(string_append(str_lit("its signature says `"), string_append(x, string_append(str_lit("` is a macro of `"), string_append(shown, string_append(str_lit("`, and its expansion defines one of "), str_lit("another signature")))))))? {});
                    } else {
                        es = cdr(es);
                        continue;
                    }
                }
            }
        }
    }

    pub fn syntax_held(mx_fail: Fails, name: Symbol, s: &'static Syn, from: Int) -> Result<(), Unwind> {
        let m = macro_of(name, get(defined()));
        if null_p(m) {
            Ok(())
        } else {
            let tagcase_ = car(m).0;
            match *tagcase_ {
                Sty::SExport(body, b) => {
                    let tagcase_ = b;
                    match *tagcase_ {
                        MxTypesBind::BindRib(es) => {
                            Ok(syntax_held_each(mx_fail, name, s, from, es)?)
                        }
                        _ => {
                            let y = tagcase_;
                            Ok(())
                        }
                    }
                }
                _ => {
                    let y = tagcase_;
                    Ok(())
                }
            }
        }
    }

