    pub fn procedural_expanded(mx_fail: Fails, name: Symbol, s: &'static Syn, made: Int) -> Result<&'static Syn, Unwind> {
        let shown = string_append(str_lit("a use of `"), string_append(symbol_to_string(name), str_lit("`: ")));
        let in_use = lambda3(move |m: Str, a: Int, b: Int| {
            Ok(match mx_fail(string_append(shown, m), a, b)? {})
        });
        let at_use = lambda3(move |m: Str, a: Int, b: Int| {
            Ok(match mx_fail(string_append(shown, m), syn_start(s), syn_end(s))? {})
        });
        let m = car(macro_of_defined(name, get(defined())));
        let sig = m.0;
        let defn = _eq(m.3, int_lit(1));
        let contract = car(procedural_of(name)).3;
        let operands = nth(split(s), int_lit(1));
        if not(contract) {
            Ok(expand_procedural(mx_fail, name, s, made)?)
        } else {
            nodes_reset_x();
            align(in_use, int_lit(2), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>()), sig, operands, int_lit(-1), nil::<bool>())?;
            let out = expand_procedural(mx_fail, name, s, made)?;
            if _eq(get(mx_procedural_contracts()), int_lit(0)) {
                Ok(out)
            } else {
                let held = if defn {
                    defined_held(at_use, sig, operands, out, made)?;
                    nodes_reset_x();
                    align(in_use, int_lit(2), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>()), sig, operands, int_lit(-1), nil::<bool>())?
                } else {
                    int_lit(0)
                };
                let r = contract_renames(in_use, sig, operands)?;
                let fresh = r.1;
                if null_p(fresh) {
                    Ok(out)
                } else {
                    let out2 = expand_procedural(mx_fail, name, renamed_use(in_use, s, r.0)?, made)?;
                    contract_held(in_use, s, out, out2, fresh, made, if defn {
                        s_defn()
                    } else {
                        s_expr()
                    })?;
                    Ok(out)
                }
            }
        }
    }

