    pub fn contracts_of(ps: Pvars, binders: MxParserTypesNames, file: Scopes) -> Result<MxNodesContracts, Unwind> {
        if null_p(ps) {
            Ok(nil::<Product_11_12<Symbol, &'static mx::Syn>>())
        } else {
            let n = car(ps).0;
            let info = car(ps).1;
            let h = info.3;
            let rest = contracts_of(cdr(ps), binders, file)?;
            if (null_p(h) || null_p(car(h).0) || not(expr_kind_p(info.0)) || names_any_p(car(car(h).0), binders)?) {
                Ok(rest)
            } else {
                let ty = car(car(h).0);
                let a = syn_start(ty);
                let b = syn_end(ty);
                let m = if null_p(file) {
                    str_lit("#%toplevel")
                } else if (syn_symbol_p(ty) && not(mx_files_name_in_p(syn_symbol(ty)?, car(file).2))) {
                    str_lit("#%fx")
                } else {
                    symbol_to_string(car(file).0)
                };
                Ok(kayak_rt::heap_cons(Product_11_12(n, mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("select"), a, b), kayak_rt::heap_cons(mk_symbol(m, a, b), kayak_rt::heap_cons(ty, kayak_rt::nil()))), a, b)), rest))
            }
        }
    }

