    pub fn pvars_of(mut mx_fail: Fails, mut fs: MxNodesFound, mut ps: Pvars, mut defn: Int) -> Result<Pvars, Unwind> {
        loop {
            if null_p(fs) {
                return Ok(ps);
            } else {
                let at = car(fs).0;
                let tagcase_ = node_kids(at);
                match *tagcase_ {
                    MxNodesKids::KPvar(n) => {
                        if (_gt(car(fs).3, int_lit(0)) && not(null_p(node_hole(at)))) {
                            match fail_at(mx_fail, str_lit("a typed part under an ellipsis: not yet"), node_syn(at))? {};
                            return Ok(ps);
                        } else if pvar_p(n, ps) {
                            match fail_at(mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is a pattern "), str_lit("variable twice")))), node_syn(at))? {};
                            return Ok(ps);
                        } else {
                            if (_eq(defn, int_lit(1)) && not(null_p(node_hole(at)))) {
                                match fail_at(mx_fail, string_append(str_lit("a macro that makes definitions has no "), string_append(str_lit("typed parts, not yet: what each use "), str_lit("defines is checked where it is"))), node_syn(at))? {};
                                return Ok(ps);
                            } else if (_eq(defn, int_lit(2)) && not(null_p(node_hole(at)))) {
                                match fail_at(mx_fail, str_lit("a macro that makes a description has no typed parts"), node_syn(at))? {};
                                return Ok(ps);
                            } else {
                                (fs, ps) = (cdr(fs), append(ps, the::<Pvars>(kayak_rt::heap_cons(Product_11_12(n, pinfo_at(at, car(fs))), kayak_rt::nil()))));
                                continue;
                            }
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        fs = cdr(fs);
                        continue;
                    }
                }
            }
        }
    }

    pub type MxTopSaid = Product_11_12<SignedOpt, List<Str>>;

    pub fn pattern_vars(mx_fail: Fails, sig: &'static Sty, pattern: &'static Syn, defn: Int, lits: MxParserTypesNames) -> Result<Product_11_12<Pvars, List<MxExportsExported>>, Unwind> {
        nodes_reset_x();
        let root = align(mx_fail, int_lit(0), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>()), sig, pattern, int_lit(-1), nil::<bool>())?;
        let mx_top_said = literals_said(mx_fail, lits, int_lit(0))?;
        let mx_nodes_found = mx_scopes_walk(mx_fail, root, env_empty(), false, int_lit(0))?;
        let e = node_export(root);
        let declared = if (_eq(defn, int_lit(1)) && not(null_p(e))) {
            the::<List<MxExportsExported>>(kayak_rt::heap_cons(mx_exports_exports_of(evaluate(mx_fail, car(e).0, car(e).1, pattern)?), kayak_rt::nil()))
        } else {
            nil::<Product_11_12<List<&'static mx::Atm>, List<Symbol>>>()
        };
        Ok(Product_11_12(pvars_of(mx_fail, mx_nodes_found, nil::<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>(), defn)?, declared))
    }

