    pub fn expand_top(mx_fail: Fails, form: &'static Syn) -> Result<SynsA, Unwind> {
        let items = list_items(form);
        if (not(null_p(items)) && syn_symbol_p(car(items)) && makes_top_defns_p(syn_symbol(car(items))?)) {
            let n = {
                made_syntax_reset_x();
                chain_begun_x(mx_fail, form)?
            };
            if _lt(n, int_lit(0)) {
                Ok(kayak_rt::heap_cons(form, kayak_rt::nil()))
            } else {
                set(budget(), n);
                Ok(at_places(expand_defn(mx_fail, form)?, syn_start(form), syn_end(form)))
            }
        } else {
            Ok(kayak_rt::heap_cons(expand(mx_fail, form)?, kayak_rt::nil()))
        }
    }

