    pub fn symbol_in(mut s: &'static Syn, mut n: Symbol) -> Result<SynsA, Unwind> {
        loop {
            if syn_symbol_p(s) {
                if symbol_eq_p(syn_symbol(s)?, n) {
                    return Ok(kayak_rt::heap_cons(s, kayak_rt::nil()));
                } else {
                    return Ok(nil::<&'static mx::Syn>());
                }
            } else if null_p(split(s)) {
                return Ok(nil::<&'static mx::Syn>());
            } else {
                let first = symbol_in(car(split(s)), n)?;
                if null_p(first) {
                    s = nth(split(s), int_lit(1));
                    continue;
                } else {
                    return Ok(first);
                }
            }
        }
    }

    #[inline]
    pub fn pattern_place(c: Clause, n: Symbol) -> Result<&'static Syn, Unwind> {
        let found = symbol_in(c.0, n)?;
        if null_p(found) {
            Ok(c.0)
        } else {
            Ok(car(found))
        }
    }

    pub fn bvar_binds(mut mx_fail: Fails, mut c: Clause, mut ps: Pvars, mut out: MxMatchBinds) -> Result<MxMatchBinds, Unwind> {
        loop {
            if null_p(ps) {
                return Ok(out);
            } else {
                let n = car(ps).0;
                let k = mx_types_kind_of(car(ps).1.0);
                if (_eq(k, int_lit(0)) || _eq(k, int_lit(10))) {
                    ps = cdr(ps);
                    continue;
                } else if _eq(k, int_lit(1)) {
                    let f = fresh_symbol(string_append(str_lit("%"), string_append(symbol_to_string(n), str_lit(":"))));
                    (ps, out) = (cdr(ps), append(out, the::<MxMatchBinds>(kayak_rt::heap_cons(Product_11_12(n, mk_symbol(symbol_to_string(f), int_lit(0), int_lit(0))), kayak_rt::nil()))));
                    continue;
                } else {
                    match fail_at(mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is not an `expr`, a "), string_append(str_lit("`lambda` or a `bvar`: a macro whose parts are "), str_lit("typed is checked once, of those alone, not yet"))))), pattern_place(c, n)?)? {};
                    return Ok(out);
                }
            }
        }
    }

