        if (_eq(len(items), int_lit(4)) && syn_symbol_p(car(items)) && string_eq_p(syn_name(car(items)), str_lit("subr")) && (not(null_p(proper_of(nth(items, int_lit(2))))) || syn_nil_p(nth(items, int_lit(2))))) {
            Ok(kayak_rt::heap_cons(car(ty), kayak_rt::nil()))
        } else {
            match fail_at(mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is a `lambda` part: its "), string_append(str_lit("type is written, `(lambda #:type (subr E (A …) "), str_lit("R))`, which its stand-in in the check is made of"))))), pattern_place(c, n)?)? {};
            Ok(nil::<&'static mx::Syn>())
        }
