        mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("lambda"), a, b), kayak_rt::heap_cons(list_at(a, b, int_lit(0), arg_params(names, proper_of(nth(proper_of(ty), int_lit(2))), a, b), nil::<&'static mx::Syn>()), kayak_rt::heap_cons(list_at(a, b, int_lit(0), kayak_rt::heap_cons(call, arg_refs(names, a, b)), nil::<&'static mx::Syn>()), kayak_rt::nil()))), a, b)
