    pub fn hole_params(mut mx_fail: Fails, mut c: Clause, mut ps: Pvars, mut a: Int, mut b: Int, mut acc: Params) -> Result<Params, Unwind> {
        loop {
            if null_p(ps) {
                return Ok(acc);
            } else {
                let n = car(ps).0;
                let info = car(ps).1;
                let h = info.3;
                let shown = symbol_to_string(n);
                let k = mx_types_kind_of(info.0);
                if not((_eq(k, int_lit(0)) || _eq(k, int_lit(10)))) {
                    ps = cdr(ps);
                    continue;
                } else if null_p(h) {
                    match fail_at(mx_fail, string_append(str_lit("`"), string_append(shown, string_append(str_lit("` has no type or effect, and another "), string_append(str_lit("part of this macro does: a macro whose parts "), string_append(str_lit("are typed is checked once, each `expr` and "), str_lit("`lambda` part typed")))))), pattern_place(c, n)?)? {};
                    return Ok(acc);
                } else {
                    let scope = hole_scope(mx_fail, c, n, reverse(info.1), c.3)?;
                    let lambda_ty = if _eq(k, int_lit(10)) {
                        written_subr(mx_fail, c, n, car(h).0)?
                    } else {
                        nil::<&'static mx::Syn>()
                    };
                    let ty = hole_part(car(h).0, str_lit("type"), shown, a, b);
                    let eff = if _eq(k, int_lit(10)) {
                        kayak_rt::heap_cons(mk_symbol(str_lit("pure"), a, b), kayak_rt::nil())
                    } else {
                        hole_part(car(h).1, str_lit("effect"), shown, a, b)
                    };
                    let hole = mk_symbol(symbol_to_string(fresh_symbol(string_append(str_lit("%h:"), string_append(shown, str_lit(":"))))), a, b);
                    let subr = mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("subr"), a, b), kayak_rt::heap_cons(car(eff), kayak_rt::heap_cons(list_at(a, b, int_lit(0), scope_types(scope), nil::<&'static mx::Syn>()), kayak_rt::heap_cons(car(ty), kayak_rt::nil())))), a, b);
                    let call = list_at(a, b, int_lit(0), kayak_rt::heap_cons(hole, scope_calls(scope, acc.1)), nil::<&'static mx::Syn>());
                    let stand_in = if null_p(lambda_ty) {
                        call
                    } else {
                        lambda_stand_in(call, car(lambda_ty), a, b)
                    };
                    let acc2 = Product_11_12_13(append(acc.0, the::<SynsA>(kayak_rt::heap_cons(mk_list(kayak_rt::heap_cons(hole, kayak_rt::heap_cons(subr, kayak_rt::nil())), a, b), kayak_rt::nil()))), append(acc.1, the::<MxMatchBinds>(kayak_rt::heap_cons(Product_11_12(n, stand_in), kayak_rt::nil()))), append(acc.2, append(cdr(ty), cdr(eff))));
                    (ps, acc) = (cdr(ps), acc2);
                    continue;
                }
            }
        }
    }

    pub fn template_check(mx_fail: Fails, n: Symbol, m: Macro, c: Clause) -> Result<&'static Syn, Unwind> {
        let template = c.1;
        let a = syn_start(template);
        let b = syn_end(template);
        let binders = bvar_binds(mx_fail, c, c.3, nil::<Product_11_12<Symbol, &'static mx::Syn>>())?;
        let made = hole_params(mx_fail, c, c.3, a, b, Product_11_12_13(the::<SynsA>(nil::<&'static mx::Syn>()), binders, m.2))?;
        let body = {
            set(checking(), true);
            def_env_x(int_lit(0), c.5);
            let x = transcribe(mx_fail, c, template, nil::<bool>(), made.1, int_lit(0))?;
            set(checking(), false);
            x
        };
        let params = made.0;
        let poly = made.2;
        let lam = mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("lambda"), a, b), kayak_rt::heap_cons(list_at(a, b, int_lit(0), params, nil::<&'static mx::Syn>()), kayak_rt::heap_cons(body, kayak_rt::nil()))), a, b);
        let proc = if null_p(poly) {
            lam
        } else {
            mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("plambda"), a, b), kayak_rt::heap_cons(mk_list(poly, a, b), kayak_rt::heap_cons(lam, kayak_rt::nil()))), a, b)
        };
        let hidden = fresh_symbol(string_append(str_lit("%template:"), string_append(symbol_to_string(n), str_lit(":"))));
        Ok(mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("define"), a, b), kayak_rt::heap_cons(atom(kayak_rt::value::ToValue::to_value(hidden), a, b, int_lit(0)), kayak_rt::heap_cons(proc, kayak_rt::nil()))), a, b))
    }

    pub fn checks_of(mut mx_fail: Fails, mut n: Symbol, mut m: Macro, mut cs: Clauses) -> Result<SynsA, Unwind> {
        loop {
            if null_p(cs) {
                return Ok(nil::<&'static mx::Syn>());
            } else if mx_templates_untyped_p(car(cs).3) {
                cs = cdr(cs);
                continue;
            } else {
                let c = template_check(mx_fail, n, m, car(cs))?;
                return Ok(kayak_rt::heap_cons(c, checks_of(mx_fail, n, m, cdr(cs))?));
            }
        }
    }

