    pub fn give_each(mut mx_fail: Fails, mut made: Mades, mut own: MacroEnv, mut own_marks: Marked, mut mx_nodes_scope: MxNodesScope, mut mx_files_filter: List<MxFilesFilter>, mut first: &'static Syn) -> Result<(), Unwind> {
        loop {
            if null_p(made) {
                return Ok(());
            } else {
                let n = car(made).0;
                let k = own_mark(n, own_marks);
                let internal = car(internal_of(n, mx_nodes_scope.3));
                if _gt(k, int_lit(0)) {
                    if (not(car(made).1) && taken_p(n, mx_files_filter)?) {
                        if (macro_p(n) || _gt(own_mark(n, get(marks())), int_lit(0))) {
                            match fail_at(mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is defined already: "), str_lit("a file's trailmark may not be defined again")))), first)? {}
                        } else {
                            set(marks(), kayak_rt::heap_cons(Product_11_12(n, k), get(marks())))
                        }
                    } else {
                        ()
                    };
                    set(marks(), kayak_rt::heap_cons(Product_11_12(internal, k), get(marks())));
                    made = cdr(made);
                    continue;
                } else {
                    let m = car(macro_of(n, own));
                    if (not(car(made).1) && taken_p(n, mx_files_filter)?) {
                        if macro_p(n) {
                            match fail_at(mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is a macro defined "), str_lit("already: a file's may not be defined again")))), first)? {}
                        } else {
                            set(defined(), kayak_rt::heap_cons(Product_11_12(n, m), get(defined())))
                        }
                    } else {
                        ()
                    };
                    set(defined(), kayak_rt::heap_cons(Product_11_12(internal, m), get(defined())));
                    made = cdr(made);
                    continue;
                }
            }
        }
    }

    pub fn define_file(mx_fail: Fails, ms: List<FileMacro>, mx_nodes_scope: MxNodesScope, mx_files_filter: List<MxFilesFilter>) -> Result<MxParserTypesNames, Unwind> {
        let (program, program_marks, program_phase1) = (get(defined()), get(marks()), phase1_forms_now());
        set(defined(), nil::<Product_11_12<Symbol, Product_11_12_13_14<&'static mx::Sty, List<Product_11_12_13_14_15_16_17_18<&'static mx::Syn, &'static mx::Syn, List<Product_11_12<List<bool>, &'static mx::Action>>, List<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>, List<Product_11_12<Symbol, &'static mx::Syn>>, Product_11_12_13<Int, Symbol, List<Symbol>>, List<Product_11_12<Symbol, Int>>, List<Int>>>, List<&'static mx::Syn>, Int>>>());
        set(marks(), nil::<Product_11_12<Symbol, Int>>());
        phase1_forms_x(nil::<Str>());
        let made = define_each(mx_fail, ms, mx_nodes_scope)?;
        let own = get(defined());
        let own_marks = get(marks());
        set(defined(), program);
        set(marks(), program_marks);
        phase1_forms_x(program_phase1);
        give_each(mx_fail, made, own, own_marks, mx_nodes_scope, mx_files_filter, if null_p(ms) {
            atom(kayak_rt::value::Value::Nil, int_lit(0), int_lit(0), int_lit(0))
        } else {
            car(ms).0
        })?;
        Ok(shown_names(made))
    }

    pub fn file_macros(mx_fail: Fails, form: &'static Syn, path: Str, mx_files_filter: List<MxFilesFilter>, fs: Files) -> Result<MxParserTypesNames, Unwind> {
        let f = loaded_path(path, fs);
        if null_p(f) {
            match fail_at(mx_fail, string_append(str_lit("cannot read `"), string_append(path, str_lit("`"))), form)? {};
            Ok(nil::<Symbol>())
        } else if takes_modules_p(car(f).4) {
            match fail_at(mx_fail, string_append(str_lit("`"), string_append(path, string_append(str_lit("` takes module parameters: its macros "), str_lit("cannot be imported, not yet")))), form)? {};
            Ok(nil::<Symbol>())
        } else {
            let key = car(f).6;
            let base = car(f).1;
            let forms = car(f).4;
            let in_file = lambda3(move |m: Str, x: Int, y: Int| {
                if (_gt_eq(x, base) && _lt(x, _plus(base, load_base()))) {
                    let at = syn_start(form);
                    Ok(match mx_fail(in_loaded_as(fs, base, path, m, x), at, at)? {})
                } else {
                    Ok(match mx_fail(m, x, y)? {})
                }
            });
            let macros = file_syntax(forms);
            let shown = names_shown(file_items(forms)?, nil::<Symbol>(), nil::<Symbol>())?;
            let internal = internal_names(key, macro_names(macros)?);
            let mx_nodes_scope = Product_11_12_13_14_15(string_to_symbol(string_append(str_lit("%shared:"), key)), shown.0, shown.1, internal, get(standard_names()));
            Ok(define_file(in_file, macros, mx_nodes_scope, mx_files_filter)?)
        }
    }

    pub fn import_file_macros(mx_fail: Fails, form: &'static Syn, fs: Files) -> Result<SynsA, Unwind> {
        let items = proper(form);
        let a = syn_start(form);
        let b = syn_end(form);
        if not(((_eq(len(items), int_lit(2)) || _eq(len(items), int_lit(3))) && syn_symbol_p(nth(items, int_lit(1))))) {
            match fail_at(mx_fail, import_usage(), form)? {};
            Ok(nil::<&'static mx::Syn>())
        } else {
            let lib = syn_symbol(nth(items, int_lit(1)))?;
            let mx_files_filter = if _eq(len(items), int_lit(3)) {
                the::<List<MxFilesFilter>>(kayak_rt::heap_cons(name_filter(mx_fail, nth(items, int_lit(2)))?, kayak_rt::nil()))
            } else {
                nil::<Product_11_12<bool, List<&'static mx::Syn>>>()
            };
            let path = mx_files_load_of(lib, get(loads()));
            if null_p(path) {
                match fail_at(mx_fail, string_append(str_lit("`import-with-syntax` takes a name defined as "), string_append(str_lit("`(load-module \"path\")`, and `"), string_append(symbol_to_string(lib), str_lit("` is not one")))), form)? {};
                Ok(nil::<&'static mx::Syn>())
            } else {
                let exported = file_macros(mx_fail, form, car(path), mx_files_filter, fs)?;
                Ok(include_of(lib, mx_files_filter, exported, a, b)?)
            }
        }
    }

    pub fn mx_walk_walked(mx_fail: Fails, form: &'static Syn, top: bool) -> Result<Product_11_12<Int, MxNodesFound>, Unwind> {
        set(program_walk(), true);
        nodes_reset_x();
        set(unplaced(), nil::<Symbol>());
        let root = align(mx_fail, int_lit(3), nil::<Product_11_12<Symbol, Product_11_12_13_14_15<&'static mx::Sty, List<&'static mx::Level>, bool, List<Product_11_12<List<&'static mx::Syn>, List<&'static mx::Syn>>>, Int>>>(), if top {
            s_item()
        } else {
            s_expr()
        }, form, int_lit(-1), nil::<bool>())?;
        let mx_nodes_found = mx_scopes_walk(mx_fail, root, env_empty(), false, int_lit(0))?;
        set(program_walk(), false);
        Ok(Product_11_12(root, mx_nodes_found))
    }

