    pub fn targets(mut mx_nodes_found: MxNodesFound, mut kept: MxParserTypesNames, mut out: Pairs) -> Product_11_12<MxParserTypesNames, Pairs> {
        loop {
            if null_p(mx_nodes_found) {
                return Product_11_12(kept, out);
            } else {
                let (at, mx_env_indexed_env) = (car(mx_nodes_found).0, car(mx_nodes_found).1);
                let tagcase_ = node_kids(at);
                match *tagcase_ {
                    MxNodesKids::KRef(n, d, free) => {
                        if d {
                            mx_nodes_found = cdr(mx_nodes_found);
                            continue;
                        } else {
                            let b = binder_in(n, mx_env_indexed_env);
                            if _eq(b, int_lit(-1)) {
                                mx_nodes_found = cdr(mx_nodes_found);
                                continue;
                            } else if _eq(b, int_lit(-2)) {
                                (mx_nodes_found, kept) = (cdr(mx_nodes_found), kayak_rt::heap_cons(n, kept));
                                continue;
                            } else {
                                (mx_nodes_found, out) = (cdr(mx_nodes_found), kayak_rt::heap_cons(Product_11_12(at, b), out));
                                continue;
                            }
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        mx_nodes_found = cdr(mx_nodes_found);
                        continue;
                    }
                }
            }
        }
    }

