    pub fn referred(mut ps: Pairs, mut mx_parser_types_names: MxWalkRenames, mut out: MxWalkRenames) -> MxWalkRenames {
        loop {
            if null_p(ps) {
                return out;
            } else {
                let nm = mx_walk_name_at(node_path(car(ps).1), mx_parser_types_names);
                (ps, out) = (cdr(ps), if null_p(nm) {
                    out
                } else {
                    kayak_rt::heap_cons(Product_11_12(node_path(car(ps).0), car(nm)), out)
                });
                continue;
            }
        }
    }

    pub fn mx_walk_falses(mut p: Addr, mut k: Int) -> Addr {
        loop {
            if _eq(k, int_lit(0)) {
                return p;
            } else {
                (p, k) = (kayak_rt::heap_cons(false, p), _minus(k, int_lit(1)));
                continue;
            }
        }
    }

    pub fn renamed_syn(s: &'static Syn, path: Addr, rs: MxWalkRenames) -> &'static Syn {
        let tagcase_ = s;
        match *tagcase_ {
            Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                mx_eager_reader_types_lst(renamed_items(items, path, rs), d, a, b, x)
            }
            Syn::Dotted(items, tail, d, a, b, x) => {
                dotted(renamed_items(items, path, rs), renamed_syn(tail, mx_walk_falses(path, len(items)), rs), d, a, b, x)
            }
            Syn::Atom(dt, a, b, x) => {
                if string_p(dt) {
                    atom(kayak_rt::value::ToValue::to_value(str_lit("")), a, b, x)
                } else if syn_symbol_p(s) {
                    let nm = mx_walk_name_at(path, rs);
                    if null_p(nm) {
                        s
                    } else {
                        atom(kayak_rt::value::ToValue::to_value(string_to_symbol(car(nm))), a, b, x)
                    }
                } else {
                    s
                }
            }
            _ => {
                let y = tagcase_;
                s
            }
        }
    }

    pub fn renamed_items(items: SynsA, path: Addr, rs: MxWalkRenames) -> SynsA {
        if null_p(items) {
            nil::<&'static mx::Syn>()
        } else {
            kayak_rt::heap_cons(renamed_syn(car(items), kayak_rt::heap_cons(true, path), rs), renamed_items(cdr(items), kayak_rt::heap_cons(false, path), rs))
        }
    }

    pub fn alpha_renamed(mx_fail: Fails, form: &'static Syn) -> Result<&'static Syn, Unwind> {
        let w = mx_walk_walked(mx_fail, form, true)?;
        let root = w.0;
        let mx_nodes_found = w.1;
        let defined = defined_binders(mx_fail, int_lit(0), get(nnodes()), nil::<Int>())?;
        let t = targets(mx_nodes_found, nil::<Symbol>(), nil::<Product_11_12<Int, Int>>());
        let kept = append(t.0, get(unplaced()));
        let binders = sorted_binders(renamable(int_lit(0), get(nnodes()), defined, kept, nil::<Int>()), nil::<Product_11_12<Int, List<bool>>>());
        let mx_parser_types_names = mx_walk_numbered(binders, int_lit(1), nil::<Product_11_12<List<bool>, Str>>());
        let refs = referred(t.1, mx_parser_types_names, nil::<Product_11_12<List<bool>, Str>>());
        Ok(renamed_syn(form, nil::<bool>(), append(mx_parser_types_names, refs)))
    }

    #[inline]
    pub fn show_renamed(s: &'static Syn) -> Str {
        show_syn(s)
    }

    pub fn walked_one(form: &'static Syn) -> Result<Str, Unwind> {
        let r = {
            let prompt_tag__ = parse_tag();
            match (move || -> Result<_, Unwind> {
                set(walked_out(), show_renamed(alpha_renamed(&pfail_walk, form)?));
                Ok(p_ok(nil::<&'static mx::MxParserTypesTop>()))
            })() {
                Ok(v_) => v_,
                Err(u_) if u_.is(prompt_tag__) => (lambda1(move |r: &'static Presult| {
                    r
                }))(prompt_tag__.payload(u_)),
                Err(u_) => return Err(u_),
            }
        };
        set(program_walk(), false);
        let tagcase_ = r;
        match *tagcase_ {
            Presult::PErr(why, a, b) => {
                Ok(string_append(str_lit("walk: "), why))
            }
            _ => {
                let y = tagcase_;
                Ok(get(walked_out()))
            }
        }
    }

    #[inline]
    pub fn walked_forms(forms: SynsA) -> Result<List<Str>, Unwind> {
        if null_p(forms) {
            Ok(nil::<Str>())
        } else {
            Ok(kayak_rt::heap_cons(walked_one(car(forms))?, walked_forms(cdr(forms))?))
        }
    }

    pub fn value_binder_in(mut n: Symbol, mut r#as: Atms) -> Int {
        loop {
            if null_p(r#as) {
                return int_lit(-1);
            } else {
                let tagcase_ = car(r#as);
                match *tagcase_ {
                    Atm::AtmLit(b, d) => {
                        if (not(d) && {
                            let tagcase_ = node_kids(b);
                            match *tagcase_ {
                                MxNodesKids::KBinder(m, e) => {
                                    symbol_eq_p(m, n)
                                }
                                _ => {
                                    let y = tagcase_;
                                    false
                                }
                            }
                        }) {
                            return b;
                        } else {
                            r#as = cdr(r#as);
                            continue;
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        r#as = cdr(r#as);
                        continue;
                    }
                }
            }
        }
    }

