    pub fn load_shape(a: Int, module_p: bool) -> MxParserTypesShapes {
        let f = file_at(a);
        let known = if null_p(f) {
            nil::<&'static mx::MxParserTypesShape>()
        } else if module_p {
            car(f).2
        } else {
            car(f).1
        };
        if not(null_p(known)) {
            known
        } else {
            let g = file_given_at(a, get(files_given()));
            if null_p(g) {
                nil::<&'static mx::MxParserTypesShape>()
            } else {
                let v = names_find(string_to_symbol(string_append(str_lit("%shared:"), file_key(car(g), load_input_at_p(a)))), get(top_vals()));
                let s = if null_p(v) {
                    nil::<&'static mx::MxParserTypesShape>()
                } else {
                    car(v).1
                };
                let fun_p = (not(null_p(s)) && {
                    let tagcase_ = car(s);
                    match *tagcase_ {
                        MxParserTypesShape::ShFun(ps, r) => {
                            true
                        }
                        _ => {
                            let y = tagcase_;
                            false
                        }
                    }
                });
                if (module_p && fun_p) {
                    result_of(s)
                } else {
                    s
                }
            }
        }
    }

