    pub fn mark_under(mut x: Int) -> () {
        loop {
            array_set_x(get(in_included()), x, true);
            let tagcase_ = node_kids(x);
            match *tagcase_ {
                MxNodesKids::KPair(a, d) => {
                    mark_under(a);
                    x = d;
                    continue;
                }
                MxNodesKids::KForm(y) => {
                    x = y;
                    continue;
                }
                MxNodesKids::MxNodesKSeq(y) => {
                    x = y;
                    continue;
                }
                MxNodesKids::KDesc(ys) => {
                    return mark_each(ys);
                }
                _ => {
                    let y = tagcase_;
                    return ();
                }
            }
        }
    }

    pub fn mark_each(mut xs: List<Int>) -> () {
        loop {
            if null_p(xs) {
                return ();
            } else {
                mark_under(car(xs));
                xs = cdr(xs);
                continue;
            }
        }
    }

