    pub fn includes_marked(mut i: Int, mut n: Int) -> Result<(), Unwind> {
        loop {
            if _eq(i, n) {
                return Ok(());
            } else {
                if (mx_shaper_form_node_p(i) && mx_shaper_head_is_p(node_syn(i), symbol_lit(str_lit("include")))?) {
                    let m = elem(i, int_lit(1));
                    if _gt_eq(m, int_lit(0)) {
                        mark_under(m)
                    } else {
                        ()
                    }
                } else {
                    ()
                };
                i = _plus(i, int_lit(1));
                continue;
            }
        }
    }

