    pub type Source = Product_11_12_13_14_15<Int, Int, Int, Int, Symbol>;

    #[inline]
    pub fn no_source() -> Source {
        Product_11_12_13_14_15(int_lit(-1), int_lit(0), int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
    }

    pub fn source_in_list(b: Int, q: Int, i: Int) -> Source {
        let mx_list = node_syn(q);
        let n = len(proper_items(mx_list));
        let head = mx_shaper_head_of(mx_list);
        if (string_eq_p(head, str_lit("define")) && _eq(i, int_lit(1)) && _eq(n, int_lit(3))) {
            Product_11_12_13_14_15(int_lit(0), elem(q, int_lit(2)), int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
        } else if ((string_eq_p(head, str_lit("define")) || string_eq_p(head, str_lit("define*"))) && _eq(i, int_lit(1)) && _eq(n, int_lit(4))) {
            Product_11_12_13_14_15(int_lit(1), elem(q, int_lit(2)), int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
        } else if (string_eq_p(head, str_lit("define-type")) && _eq(i, int_lit(1)) && _eq(n, int_lit(3))) {
            Product_11_12_13_14_15(int_lit(1), elem(q, int_lit(2)), int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
        } else if (string_eq_p(head, str_lit("import")) && _gt_eq(i, int_lit(2))) {
            let tagcase_ = node_kids(b);
            match *tagcase_ {
                MxNodesKids::KBinder(m, d) => {
                    if d {
                        no_source()
                    } else {
                        Product_11_12_13_14_15(int_lit(2), elem(q, int_lit(1)), int_lit(0), int_lit(0), m)
                    }
                }
                _ => {
                    let y = tagcase_;
                    no_source()
                }
            }
        } else if (_eq(i, int_lit(0)) && (_eq(n, int_lit(2)) || _eq(n, int_lit(3)))) {
            let r = position(q).0;
            let fk = if _gt_eq(r, int_lit(0)) {
                position(r)
            } else {
                Product_11_12(int_lit(-1), int_lit(0))
            };
            let f = fk.0;
            let k = fk.1;
            let second = elem(q, int_lit(1));
            let fh = if _gt_eq(f, int_lit(0)) {
                mx_shaper_head_of(node_syn(f))
            } else {
                str_lit("")
            };
            if (_eq(k, int_lit(1)) && (string_eq_p(fh, str_lit("let")) || string_eq_p(fh, str_lit("let*")) || string_eq_p(fh, str_lit("par")))) {
                Product_11_12_13_14_15(int_lit(0), second, int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
            } else if ((_eq(k, int_lit(1)) && (string_eq_p(fh, str_lit("letrec")) || string_eq_p(fh, str_lit("lambda")) || string_eq_p(fh, str_lit("module-parameters")))) || (_eq(k, int_lit(2)) && string_eq_p(fh, str_lit("rlambda")))) {
                Product_11_12_13_14_15(int_lit(1), second, int_lit(0), int_lit(0), symbol_lit(str_lit("-")))
            } else {
                no_source()
            }
        } else {
            no_source()
        }
    }

    pub fn declared_type(mut at: Int) -> Int {
        loop {
            let pi = position(at);
            let p = pi.0;
            let i = pi.1;
            let h = if _gt_eq(p, int_lit(0)) {
                mx_shaper_head_of(node_syn(p))
            } else {
                str_lit("")
            };
            if _lt(p, int_lit(0)) {
                return int_lit(-1);
            } else if (string_eq_p(h, str_lit("plambda")) && _eq(i, int_lit(2))) {
                at = p;
                continue;
            } else if ((string_eq_p(h, str_lit("define")) || string_eq_p(h, str_lit("define*"))) && _eq(i, int_lit(3))) {
                return elem(p, int_lit(2));
            } else if (string_eq_p(h, str_lit("the")) && _eq(i, int_lit(2))) {
                return elem(p, int_lit(1));
            } else {
                return int_lit(-1);
            }
        }
    }

    pub fn dependent_p(s: &'static Syn) -> bool {
        let items = proper_items(s);
        (_eq(len(items), int_lit(3)) && syn_symbol_p(nth(items, int_lit(1))) && string_eq_p(syn_name(nth(items, int_lit(1))), str_lit(":")))
    }

    pub fn param_of_type(mut t: Int, mut k: Int) -> Result<Source, Unwind> {
        loop {
            let s = node_syn(t);
            let h = mx_shaper_head_of(s);
            let items = proper_items(s);
            if syn_symbol_p(s) {
                return Ok(Product_11_12_13_14_15(int_lit(3), int_lit(0), int_lit(0), k, syn_symbol(s)?));
            } else if (string_eq_p(h, str_lit("allof")) || string_eq_p(h, str_lit("poly"))) {
                let x = elem(t, if string_eq_p(h, str_lit("allof")) {
                    int_lit(1)
                } else {
                    _minus(len(items), int_lit(1))
                });
                if _lt(x, int_lit(0)) {
                    return Ok(no_source());
                } else {
                    t = x;
                    continue;
                }
            } else if (string_eq_p(h, str_lit("->")) || string_eq_p(h, str_lit("subr"))) {
                let conv = (string_eq_p(h, str_lit("subr")) && _gt(len(items), int_lit(1)) && string_eq_p(mx_shaper_head_of(nth(items, int_lit(1))), str_lit("conv")));
                let ps = elem(t, if string_eq_p(h, str_lit("->")) {
                    int_lit(1)
                } else if conv {
                    int_lit(3)
                } else {
                    int_lit(2)
                });
                let p = if _lt(ps, int_lit(0)) {
                    int_lit(-1)
                } else {
                    elem(ps, k)
                };
                if _lt(p, int_lit(0)) {
                    return Ok(no_source());
                } else if dependent_p(node_syn(p)) {
                    return Ok(Product_11_12_13_14_15(int_lit(1), elem(p, int_lit(2)), int_lit(0), int_lit(0), symbol_lit(str_lit("-"))));
                } else {
                    return Ok(Product_11_12_13_14_15(int_lit(1), p, int_lit(0), int_lit(0), symbol_lit(str_lit("-"))));
                }
            } else {
                return Ok(no_source());
            }
        }
    }

