    pub fn operator(at: Int) -> Int {
        let tagcase_ = node_kids(at);
        match *tagcase_ {
            MxNodesKids::KForm(x) => {
                if mx_walk_addr_eq_p(node_path(x), node_path(at)) {
                    let tagcase_ = node_kids(x);
                    match *tagcase_ {
                        MxNodesKids::KPair(f, d) => {
                            f
                        }
                        _ => {
                            let y = tagcase_;
                            int_lit(-1)
                        }
                    }
                } else {
                    int_lit(-1)
                }
            }
            _ => {
                let y = tagcase_;
                int_lit(-1)
            }
        }
    }

    pub fn argument_param(f: Int, i: Int) -> Source {
        let pj = position(f);
        let app = pj.0;
        let j = pj.1;
        let op = if _gt_eq(app, int_lit(0)) {
            operator(app)
        } else {
            int_lit(-1)
        };
        if (_gt_eq(op, int_lit(0)) && _gt_eq(j, int_lit(1))) {
            Product_11_12_13_14_15(int_lit(4), op, _minus(j, int_lit(1)), i, symbol_lit(str_lit("-")))
        } else {
            no_source()
        }
    }

    pub fn mx_shaper_source_of(mx_fail: Fails, b: Int) -> Result<Source, Unwind> {
        let pq = position(b);
        let q = pq.0;
        let i = pq.1;
        if _lt(q, int_lit(0)) {
            Ok(no_source())
        } else {
            let fq = position(q);
            if (_eq(fq.1, int_lit(1)) && _gt_eq(fq.0, int_lit(0)) && string_eq_p(mx_shaper_head_of(node_syn(fq.0)), str_lit("lambda"))) {
                let d = declared_param(fq.0, i)?;
                if _gt_eq(d.0, int_lit(0)) {
                    Ok(d)
                } else {
                    Ok(argument_param(fq.0, i))
                }
            } else if (_eq(i, int_lit(0)) && _eq(fq.1, int_lit(1)) && _gt_eq(fq.0, int_lit(0)) && string_eq_p(mx_shaper_head_of(node_syn(fq.0)), str_lit("define-type"))) {
                Ok(Product_11_12_13_14_15(int_lit(1), elem(fq.0, int_lit(2)), int_lit(0), int_lit(0), symbol_lit(str_lit("-"))))
            } else {
                Ok(source_in_list(b, q, i))
            }
        }
    }

