    pub fn top_shape(n: Symbol, d: bool) -> MxParserTypesShapes {
        let name = symbol_to_string(n);
        let shared = (not(d) && _gt(string_length(name), int_lit(8)) && string_eq_p(substring(name, int_lit(0), int_lit(8)), str_lit("%shared:")));
        let m = if get(shaping_top()) {
            names_find(n, get(if d {
                top_descs()
            } else {
                top_vals()
            }))
        } else {
            nil::<Product_11_12<Symbol, List<&'static mx::MxParserTypesShape>>>()
        };
        if (not(null_p(m)) && not(null_p(car(m).1))) {
            car(m).1
        } else if shared {
            let f = file_shape_keyed(substring(name, int_lit(8), string_length(name)), get(file_shapes()));
            if null_p(f) {
                global_shape(n, d)
            } else {
                car(f).1
            }
        } else {
            global_shape(n, d)
        }
    }

