    pub fn moduleof_shape(mut mx_fail: Fails, mut ms: List<&'static Syn>, mut es: List<Int>, mut vs: MxParserTypesMembers, mut ds: MxParserTypesMembers) -> Result<MxParserTypesShapes, Unwind> {
        loop {
            if null_p(ms) {
                return Ok(one(sh_module(reverse(vs), reverse(ds))));
            } else {
                let parts = proper_items(car(ms));
                let x = if null_p(es) {
                    int_lit(-1)
                } else {
                    car(es)
                };
                let word = if (not(null_p(parts)) && syn_symbol_p(car(parts))) {
                    syn_name(car(parts))
                } else {
                    str_lit("")
                };
                let second = if _gt(len(parts), int_lit(1)) {
                    nth(parts, int_lit(1))
                } else {
                    car(ms)
                };
                let at = if (syn_keyword_p(second) && not(string_eq_p(word, str_lit("val"))) && _eq(len(parts), int_lit(4))) {
                    int_lit(3)
                } else {
                    int_lit(2)
                };
                let mx_parser_types_names = if syn_symbol_p(second) {
                    kayak_rt::heap_cons(syn_symbol(second)?, kayak_rt::nil())
                } else if syn_keyword_p(second) {
                    let tagcase_ = second;
                    match *tagcase_ {
                        Syn::Atom(d, a, b, x) => {
                            if mx_keyword_p(d) {
                                kayak_rt::heap_cons(mx_keyword_to_symbol(d), kayak_rt::nil())
                            } else {
                                nil::<Symbol>()
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            nil::<Symbol>()
                        }
                    }
                } else if null_p(proper_items(second)) {
                    nil::<Symbol>()
                } else if string_eq_p(word, str_lit("abs")) {
                    if all_symbols_p(proper_items(second)) {
                        mx_shaper_symbols_of(proper_items(second))?
                    } else {
                        mx_shaper_symbols_of(kayak_rt::heap_cons(car(proper_items(second)), kayak_rt::nil()))?
                    }
                } else {
                    mx_shaper_symbols_of(kayak_rt::heap_cons(car(proper_items(second)), kayak_rt::nil()))?
                };
                let t = lambda0(move || {
                    if _lt(x, int_lit(0)) {
                        Ok(nil::<&'static mx::MxParserTypesShape>())
                    } else {
                        let y = elem(x, at);
                        if _lt(y, int_lit(0)) {
                            Ok(nil::<&'static mx::MxParserTypesShape>())
                        } else {
                            Ok(mx_shaper_ty_shape(mx_fail, y)?)
                        }
                    }
                });
                if (_lt(len(parts), int_lit(2)) || (null_p(mx_parser_types_names) && not(string_eq_p(word, str_lit("abs"))))) {
                    return Ok(nil::<&'static mx::MxParserTypesShape>());
                } else if string_eq_p(word, str_lit("val")) {
                    (ms, es, vs) = (cdr(ms), if null_p(es) {
                        nil::<Int>()
                    } else {
                        cdr(es)
                    }, kayak_rt::heap_cons(Product_11_12(car(mx_parser_types_names), t()?), vs));
                    continue;
                } else if string_eq_p(word, str_lit("abs")) {
                    (ms, es, ds) = (cdr(ms), if null_p(es) {
                        nil::<Int>()
                    } else {
                        cdr(es)
                    }, abs_onto(mx_parser_types_names, ds));
                    continue;
                } else if string_eq_p(word, str_lit("desc")) {
                    (ms, es, ds) = (cdr(ms), if null_p(es) {
                        nil::<Int>()
                    } else {
                        cdr(es)
                    }, kayak_rt::heap_cons(Product_11_12(car(mx_parser_types_names), t()?), ds));
                    continue;
                } else {
                    return Ok(nil::<&'static mx::MxParserTypesShape>());
                }
            }
        }
    }

