    pub fn writings(mut k: Int, mut n: Int, mut out: List<Writing>) -> Result<List<Writing>, Unwind> {
        loop {
            if _eq(k, n) {
                return Ok(out);
            } else {
                (k, out) = (_plus(k, int_lit(1)), {
                    let s = node_syn(k);
                    if (mx_shaper_form_node_p(k) && opens_p(s)? && null_p(writing_at(node_path(k), out)) && not(toplevel_or_fx_p(s)) && _gt_eq(elem(k, int_lit(1)), int_lit(0))) {
                        let a = asked_of(elem(k, int_lit(1)));
                        kayak_rt::heap_cons(Product_11_12(node_path(k), if a.1 {
                            nil::<&'static mx::Syn>()
                        } else {
                            kayak_rt::heap_cons(asked_written(a, s), kayak_rt::nil())
                        }), out)
                    } else {
                        out
                    }
                });
                continue;
            }
        }
    }

