    pub fn written_items(items: SynsA, ws: List<Writing>, here: List<List<&'static Syn>>, k: Int, a: Int, b: Int) -> Result<SynsA, Unwind> {
        let record = if null_p(here) {
            the::<SynsA>(nil::<&'static mx::Syn>())
        } else {
            kayak_rt::heap_cons(atom(kayak_rt::value::ToValue::to_value(mx_symbol_to_keyword(symbol_lit(str_lit("relied")))), a, b, int_lit(0)), kayak_rt::heap_cons(if null_p(car(here)) {
                mk_symbol(str_lit("#f"), a, b)
            } else {
                car(car(here))
            }, kayak_rt::nil()))
        };
        if null_p(items) {
            if _eq(k, int_lit(2)) {
                Ok(record)
            } else {
                Ok(nil::<&'static mx::Syn>())
            }
        } else if (_eq(k, int_lit(2)) && not(null_p(here))) {
            Ok(append(record, written_items(items, ws, nil::<List<&'static mx::Syn>>(), k, a, b)?))
        } else {
            Ok(kayak_rt::heap_cons(written_under(car(items), step_taken(ws, true))?, written_items(cdr(items), step_taken(ws, false), here, _plus(k, int_lit(1)), a, b)?))
        }
    }

