    pub fn relied_in_p(mut s: &'static Syn) -> bool {
        loop {
            let tagcase_ = s;
            match *tagcase_ {
                Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                    return (relied_at_2_p(items) || any_relied_p(items));
                }
                Syn::Dotted(items, t, d, a, b, x) => {
                    if relied_at_2_p(items) {
                        return true;
                    } else {
                        if any_relied_p(items) {
                            return true;
                        } else {
                            s = t;
                            continue;
                        }
                    }
                }
                _ => {
                    let y = tagcase_;
                    return false;
                }
            }
        }
    }

