    pub fn fasl_kept_x(key: Str, forms: SynsA, input_p: bool) -> Result<(), Unwind> {
        if (null_p(forms) || not(null_p(cdr(forms)))) {
            Ok(())
        } else {
            let form = unshaped(car(forms));
            let r = {
                let prompt_tag__ = parse_tag();
                match (move || -> Result<_, Unwind> {
                    set(file_out(), shaped(&pfail_walk, form, false)?);
                    Ok(p_ok(nil::<&'static mx::MxParserTypesTop>()))
                })() {
                    Ok(v_) => v_,
                    Err(u_) if u_.is(prompt_tag__) => (lambda1(move |r: &'static Presult| {
                        r
                    }))(prompt_tag__.payload(u_)),
                    Err(u_) => return Err(u_),
                }
            };
            let ok = {
                set(program_walk(), false);
                let tagcase_ = r;
                match *tagcase_ {
                    Presult::PErr(why, a, b) => {
                        false
                    }
                    _ => {
                        let y = tagcase_;
                        true
                    }
                }
            };
            let whole = if ok {
                get(file_out()).1
            } else {
                nil::<&'static mx::MxParserTypesShape>()
            };
            let m = if input_p {
                mx_shaper_member_shape(whole, symbol_lit(str_lit("input")), false)
            } else {
                whole
            };
            let fun = (not(null_p(m)) && {
                let tagcase_ = car(m);
                match *tagcase_ {
                    MxParserTypesShape::ShFun(ps, r) => {
                        true
                    }
                    _ => {
                        let y = tagcase_;
                        false
                    }
                }
            });
            Ok(set(file_shapes(), file_shape_replaced(key, Product_11_12_13_14(key, m, if fun {
                result_of(m)
            } else {
                m
            }, forms), get(file_shapes()))))
        }
    }

