    pub fn sealed_written(mx_fail: Fails, s: &'static Syn) -> Result<&'static Syn, Unwind> {
        let tagcase_ = s;
        match *tagcase_ {
            Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                let h = head_sym(s)?;
                if (symbol_eq_p(h, symbol_lit(str_lit("quote"))) || symbol_eq_p(h, symbol_lit(str_lit("quasiquote"))) || symbol_eq_p(h, symbol_lit(str_lit("%datum")))) {
                    Ok(s)
                } else if (not(symbol_eq_p(h, no_head())) && not(null_p(shape_named(h)))) {
                    match mx_fail(string_append(str_lit("`"), string_append(symbol_to_string(h), string_append(str_lit("` is a shape, not a macro: it is "), str_lit("written as a `define`'s or `the`'s type")))), a, b)? {};
                    Ok(s)
                } else {
                    let xs = sealed_each(mx_fail, items)?;
                    let n = len(xs);
                    let ys = if (symbol_eq_p(h, symbol_lit(str_lit("define"))) && _eq(n, int_lit(4)) && not(null_p(mx_shapes_shape_of(nth(xs, int_lit(2)))?))) {
                        kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(nth(xs, int_lit(1)), kayak_rt::heap_cons(mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("the"), a, b), kayak_rt::heap_cons(car(mx_shapes_shape_of(nth(xs, int_lit(2)))?), kayak_rt::heap_cons(nth(xs, int_lit(3)), kayak_rt::nil()))), a, b), kayak_rt::nil())))
                    } else if (symbol_eq_p(h, symbol_lit(str_lit("the"))) && _eq(n, int_lit(3)) && not(null_p(mx_shapes_shape_of(nth(xs, int_lit(1)))?))) {
                        kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(car(mx_shapes_shape_of(nth(xs, int_lit(1)))?), kayak_rt::heap_cons(nth(xs, int_lit(2)), kayak_rt::nil())))
                    } else {
                        xs
                    };
                    if same_items_p(ys, items) {
                        Ok(s)
                    } else {
                        Ok(mx_eager_reader_types_lst(ys, kayak_rt::value::list(syn_datums(ys)), a, b, x))
                    }
                }
            }
            Syn::Dotted(items, t, d, a, b, x) => {
                let (xs, t2) = (sealed_each(mx_fail, items)?, sealed_written(mx_fail, t)?);
                if (same_items_p(xs, items) && false) {
                    Ok(s)
                } else {
                    Ok(dotted(xs, t2, kayak_rt::value::list(syn_datums(xs)), a, b, x))
                }
            }
            _ => {
                let y = tagcase_;
                Ok(s)
            }
        }
    }

